type Payloads = {
  NotStarted: Record<string, never>;
  InvalidConfig: { key: "NATS_URL" };
  DownloadFailed: { url: string; status: number };
  ChecksumMismatch: { file: string };
  ServerStopped: { output: string; storeDir: string };
};

export declare namespace Errors {
  type Name = keyof Payloads;
  type Payload<N extends Name> = Payloads[N];
  type Of<N extends Name = Name> = Error & {
    readonly kind: N;
    readonly payload: Payloads[N];
  };
}

export function raise<N extends Errors.Name>(kind: N, payload: Errors.Payload<N>): never {
  throw Object.assign(new Error(kind), { kind, payload });
}

/** Narrow at a catch boundary; rethrow errors from other packages. */
export function isError<N extends Errors.Name>(value: unknown, kind: N): value is Errors.Of<N> {
  return value instanceof Error && (value as Partial<Errors.Of>).kind === kind;
}

import { extension, operation, resource, tag } from "@tinker/core";
import type { Namespace, Observe, Operation, Scope } from "@tinker/core";
import type { Msg, MsgHdrs, NatsConnection, Subscription } from "@nats-io/transport-node";
import { raise } from "./errors.ts";

export { isError } from "./errors.ts";
export type { Errors } from "./errors.ts";

export declare namespace Nats {
  /** Payload bytes belong to this delivery; no client objects cross into the app. */
  type Message = { subject: string; payload: Uint8Array };
  type Load<T> = () => Operation.Handle<T, Message> | PromiseLike<Operation.Handle<T, Message>>;
  type Row = { subject: string; load: Load<unknown> };
  type Config = {
    url: string;
    /** Borrowed from a dev host. Only this piece's subscriptions close with the scope. */
    connection?: NatsConnection;
  };
  type Wiring = {
    env: { NATS_URL?: string };
    /** Borrowed from a dev host. Only this piece's subscriptions close with the scope. */
    connection?: NatsConnection;
  };
  /** Resolving the resource prepares this namespace's incoming subscriptions too. */
  type Connection = { send(message: Message, span?: Observe.Span): void };
}

const closedConnection: Nats.Connection = {
  send: () => raise("NotStarted", {}),
};

/** One row per subject. Wildcards follow NATS subject rules. */
export function subscribe<T>(
  subject: string,
  op: Operation.Handle<T, Nats.Message> | Nats.Load<T>,
): Nats.Row {
  return { subject, load: typeof op === "function" ? op : () => op };
}

/** Share one definition across roots and namespaces. Each namespace owns its connection
 * and subscriptions until the root closes; a lent SDK connection stays with its lender.
 * The extension checks the initial config before later starts and prepares its namespace
 * after them. Resolving `connection` or publishing prepares another selected namespace.
 * Each definition needs its own config and driver identities to keep separate buses apart. */
export function nats(rows: readonly Nats.Row[], wiring?: Nats.Wiring) {
  const config = tag<Nats.Config>({ label: "nats.config" });
  const settings = resource({
    label: "nats.settings",
    target: "namespace",
    depends: { config: config.optional },
    factory: ({ config }) => ({
      url: readUrl(config.present ? config.value.url : wiring?.env.NATS_URL),
      connection: config.present ? config.value.connection : wiring?.connection,
    }),
  });
  const driver = resource({
    label: "nats.driver",
    target: "scope",
    factory: (_deps, ctx) => {
      const driver = new Driver();
      ctx.defer(() => driver.finish());
      return driver;
    },
  });
  const connection = resource({
    label: "nats.connection",
    target: "namespace",
    depends: { settings, driver },
    factory: async ({ settings, driver }, ctx): Promise<Nats.Connection> => {
      const scope = driver.readScope();
      const service = new Connection(!settings.connection);
      driver.connections.add(service);
      ctx.defer(async () => {
        try {
          await service.close();
        } finally {
          driver.connections.delete(service);
        }
      });
      const { connect, headers } = await import("@nats-io/transport-node");
      ctx.signal.throwIfAborted();
      const client = settings.connection ?? (await connect({ servers: settings.url }));
      service.attach(client, headers);
      ctx.signal.throwIfAborted();
      if (!driver.stopping) {
        for (const row of rows) {
          const receive = await row.load();
          ctx.signal.throwIfAborted();
          if (driver.stopping) break;
          service.subscriptions.push(
            client.subscribe(row.subject, {
              callback: (error, message) => {
                if (ctx.signal.aborted) return;
                const work = deliver(scope, ctx.ns, row.subject, receive, error, message);
                service.track(work);
              },
            }),
          );
        }
        await client.flush();
      }
      return { send: service.send };
    },
  });
  const bridge = extension({
    label: "nats",
    hooks: {
      start: async (event) => {
        const owner = event.resolve(driver);
        owner.start(event.scope);
        event.resolve(settings);
        await event.next();
        return owner.stopping ? closedConnection : event.resolve(connection);
      },
      close: async (event) => {
        const owner = event.resolve(driver);
        if (event.options.graceful) await owner.quiet();
        return event.next();
      },
    },
  });
  const publish = operation({
    label: "nats.publish",
    depends: { connection },
    run: async ({ connection }, ctx: Operation.Ctx<Nats.Message>) => {
      connection.send(ctx.input, ctx.obs.span);
    },
  });
  return { extension: bridge, publish, config, connection };
}

class Driver {
  private scope: Scope.Handle | undefined;
  readonly connections = new Set<Connection>();
  stopping = false;

  start(scope: Scope.Handle): void {
    this.scope = scope;
  }

  readScope(): Scope.Handle {
    if (!this.scope) raise("NotStarted", {});
    return this.scope;
  }

  async quiet(): Promise<void> {
    this.stopping = true;
    /** Resource cleanup reports a failed drain after the scope has closed its sessions. */
    await Promise.allSettled([...this.connections].map((connection) => connection.quiet()));
  }

  finish(): void {
    this.stopping = true;
    this.scope = undefined;
  }
}

class Connection {
  readonly subscriptions: Subscription[] = [];
  private pending = new Set<Promise<void>>();
  private live: { client: NatsConnection; headers: () => MsgHdrs } | undefined;
  private owned: boolean;
  private stopping: Promise<void> | undefined;
  private closing: Promise<void> | undefined;

  constructor(owned: boolean) {
    this.owned = owned;
  }

  attach(client: NatsConnection, headers: () => MsgHdrs): void {
    this.live = { client, headers };
  }

  readonly send = (message: Nats.Message, span?: Observe.Span): void => {
    const live = this.live;
    if (!live) raise("NotStarted", {});
    if (span) {
      const carrier = live.headers();
      carrier.set("traceparent", `00-${span.traceId}-${span.spanId}-${span.sampled ? "01" : "00"}`);
      live.client.publish(message.subject, message.payload, { headers: carrier });
    } else {
      live.client.publish(message.subject, message.payload);
    }
  };

  track(work: Promise<void>): void {
    this.pending.add(work);
    const settled = () => this.pending.delete(work);
    work.then(settled, settled);
  }

  quiet(): Promise<void> {
    return (this.stopping ??= stopSubscriptions(this.subscriptions, this.pending));
  }

  close(): Promise<void> {
    return (this.closing ??= this.finish());
  }

  private async finish(): Promise<void> {
    try {
      await this.quiet();
      if (this.owned) await this.live?.client.drain();
    } catch (error) {
      /** A failed final flush must still release an owned connection. */
      if (this.owned) await this.live?.client.close();
      throw error;
    } finally {
      this.live = undefined;
      this.subscriptions.length = 0;
      this.pending.clear();
    }
  }
}

/** The NATS carrier follows the same W3C validation as Hono: an invalid
 * or absent header clears any root seed before opening the message session. */
function readTraceparent(header: string | undefined): Observe.Trace | null {
  if (!header) return null;
  const match =
    /^(?<version>[0-9a-f]{2})-(?<traceId>[0-9a-f]{32})-(?<parentSpanId>[0-9a-f]{16})-(?<flags>[0-9a-f]{2})(?<suffix>-.*)?$/.exec(
      header,
    );
  if (!match) return null;
  const { version, traceId, parentSpanId, flags, suffix } = match.groups!;
  if (version === "ff" || (version === "00" && suffix !== undefined)) return null;
  if (/^0+$/.test(traceId) || /^0+$/.test(parentSpanId)) return null;
  return { traceId, parentSpanId, sampled: (Number.parseInt(flags, 16) & 1) === 1 };
}

function readUrl(value: string | undefined): string {
  const url = URL.parse(String(value));
  if (!url || !["nats:", "tls:"].includes(url.protocol) || !url.hostname) {
    raise("InvalidConfig", { key: "NATS_URL" });
  }
  return url.href;
}

function deliver(
  scope: Scope.Handle,
  ns: readonly Namespace[] | undefined,
  subject: string,
  receive: Operation.Handle<unknown, Nats.Message>,
  error: Error | null,
  message: Msg,
): Promise<void> {
  return scope.session(
    { ns, trace: readTraceparent(error ? undefined : message.headers?.get("traceparent")) },
    (session) =>
      session.run({
        label: `nats ${subject}`,
        depends: { receive },
        run: async ({ receive }, ctx) => {
          if (error) {
            ctx.log.error("nats subscription failed", { subject, error });
            return;
          }
          const result = await receive.settle({
            input: { subject: message.subject, payload: new Uint8Array(message.data) },
          });
          if (result.status === "failed") {
            ctx.log.error("nats operation failed", {
              subject: message.subject,
              error: result.error,
            });
          }
        },
      }),
  );
}

async function stopSubscriptions(
  subscriptions: Subscription[],
  pending: Set<Promise<void>>,
): Promise<void> {
  await Promise.allSettled(
    subscriptions
      .filter((subscription) => !subscription.isClosed())
      .map((subscription) => subscription.drain()),
  );
  await Promise.all(pending);
}

import { createHash } from "node:crypto";
import { execFile, spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdir, mkdtemp, readFile, rename, rm, writeFile } from "node:fs/promises";
import { homedir, tmpdir } from "node:os";
import { isAbsolute, join, sep } from "node:path";
import { promisify } from "node:util";
import { raise } from "./errors.ts";

export { isError } from "./errors.ts";

const release = "https://github.com/nats-io/nats-server/releases/download/v2.15.0";
/** A sandbox can lend a populated cache without changing the process's home (XDG). */
const cacheHome = process.env.XDG_CACHE_HOME ?? "";
const cache = join(
  isAbsolute(cacheHome) ? cacheHome : join(homedir(), ".cache"),
  "tinkered",
  "nats-server",
  "2.15.0",
);
const architectures: Record<string, string> = { x64: "amd64", ia32: "386", arm: "arm7" };
const host = `${process.platform === "win32" ? "windows" : process.platform}-${architectures[process.arch] ?? process.arch}`;
const stem = `nats-server-v2.15.0-${host}`;
const windows = process.platform === "win32";
const archive = `${stem}.${windows ? "zip" : "tar.gz"}`;
const binary = windows ? "nats-server.exe" : "nats-server";
const execute = promisify(execFile);

export declare namespace NatsServer {
  type Install = {
    /** Tests can serve downloads locally on a cache miss. Defaults to the official GitHub release. */
    downloadBase?: string;
  };
  type Handle = {
    url: string;
    /** Loopback-only NATS monitor for test assertions about open connections. */
    monitorUrl: string;
    /** The temporary store belongs to this server and is removed by close. */
    storeDir: string;
    /** The caller owns the server. Close waits for exit and removes its temp store. */
    close(): Promise<void>;
  };
}

/** Fetch the official release once into the user's home cache.
 * Verify the saved archive against the release's SHA256SUMS on every call.
 * A custom cache directory lets tests check damaged downloads without changing the shared cache.
 * The archive and SHA256SUMS are kept beside the extracted release folder. */
export async function installNatsServer(
  directory = cache,
  { downloadBase = release }: NatsServer.Install = {},
): Promise<string> {
  await mkdir(directory, { recursive: true });
  const cached = existsSync(join(directory, archive));
  const read = cached
    ? (name: string) => readFile(join(directory, name))
    : (name: string) => fetchFile(`${downloadBase}/${name}`);
  const checksums = await read("SHA256SUMS");
  const bytes = await read(archive);
  checkArchive(bytes, checksums.toString());
  if (!cached) {
    const staging = await mkdtemp(join(directory, sep));
    try {
      await writeFile(join(staging, archive), bytes);
      await writeFile(join(staging, "SHA256SUMS"), checksums);
      await rename(join(staging, "SHA256SUMS"), join(directory, "SHA256SUMS"));
      await rename(join(staging, archive), join(directory, archive));
    } finally {
      await rm(staging, { recursive: true });
    }
  }
  const executable = join(directory, stem, binary);
  if (!existsSync(executable)) {
    const staging = await mkdtemp(join(directory, sep));
    try {
      await execute("tar", ["-xf", join(directory, archive), "-C", staging]);
      await mkdir(join(directory, stem), { recursive: true });
      await rename(join(staging, stem, binary), executable);
    } finally {
      await rm(staging, { recursive: true });
    }
  }
  return executable;
}

async function fetchFile(url: string): Promise<Buffer> {
  const response = await fetch(url);
  if (!response.ok) raise("DownloadFailed", { url, status: response.status });
  return Buffer.from(await response.arrayBuffer());
}

function checkArchive(bytes: Buffer, checksums: string): void {
  const digest = createHash("sha256").update(bytes).digest("hex");
  const match = checksums.split(/\r?\n/).includes(`${digest}  ${archive}`);
  if (!match) raise("ChecksumMismatch", { file: archive });
}

/** Start a real server on free loopback ports with its own temp store.
 * Tests may supply NATS config, such as a user's subject permissions. */
export async function startNatsServer(config = ""): Promise<NatsServer.Handle> {
  const executable = await installNatsServer();
  const store = await mkdtemp(join(tmpdir(), "tinker-nats-"));
  const configFile = join(store, "server.conf");
  await writeFile(configFile, config);
  const child = spawn(executable, [
    "-a",
    "127.0.0.1",
    "-p",
    "-1",
    "-m",
    "-1",
    "-sd",
    store,
    "-c",
    configFile,
  ]);
  const exited = new Promise<void>((resolve, reject) => {
    child.once("exit", () => resolve());
    child.once("error", reject);
  });
  let output = "";
  const ready = new Promise<{ url: string; monitorUrl: string }>((resolve) => {
    child.stderr.setEncoding("utf8").on("data", (chunk: string) => {
      output += chunk;
      const port = /Listening for client connections on 127\.0\.0\.1:(\d+)/.exec(output)?.at(1);
      const monitor = /Starting http monitor on 127\.0\.0\.1:(\d+)/.exec(output)?.at(1);
      if (port && monitor) {
        resolve({ url: `nats://127.0.0.1:${port}`, monitorUrl: `http://127.0.0.1:${monitor}` });
      }
    });
  });
  let closing: Promise<void> | undefined;
  const close = (): Promise<void> => (closing ??= stop());
  async function stop(): Promise<void> {
    child.kill();
    await exited.finally(() => rm(store, { recursive: true }));
  }
  try {
    const addresses = await Promise.race([
      ready,
      exited.then(() => raise("ServerStopped", { output, storeDir: store })),
    ]);
    return { ...addresses, storeDir: store, close };
  } catch (error) {
    await close();
    throw error;
  }
}
